      const r = h('div', { class: 'ln' + (starts[n] ? ' sc' : ''), 'data-n': n, id: 'L' + n }, [h('span', null, String(n)), h('span', null, body)]);
      if (starts[n]) r.setAttribute('data-fn', starts[n].id);
